@Service
public class NotificationDispatcherService {

    private final HttpClient httpClient = HttpClient.newBuilder()
        .connectTimeout(Duration.ofSeconds(3))
        .executor(Executors.newVirtualThreadPerTaskExecutor())
        .build();

    private final RetryRegistry retryRegistry;

    public NotificationDispatcherService(RetryRegistry retryRegistry) {
        this.retryRegistry = retryRegistry;
    }

    public CompletableFuture<Void> dispatchAsync(NotificationEvent event) {
        Retry retry = retryRegistry.retry("notificationService");
        Supplier<CompletableFuture<HttpResponse<String>>> supplier = Retry.decorateSupplier(
            retry,
            () -> httpClient.sendAsync(
                buildHttpRequest(event),
                HttpResponse.BodyHandlers.ofString()
            )
        );

        return CompletableFuture.supplyAsync(supplier)
            .thenCompose(Function.identity())
            .handle((response, throwable) -> {
                if (throwable != null) {
                    handlePermanentFailure(event, throwable);
                } else if (response.statusCode() >= 400) {
                    handleHttpError(event, response.statusCode());
                }
                return null;
            });
    }

    private HttpRequest buildHttpRequest(NotificationEvent event) {
        return HttpRequest.newBuilder()
            .uri(URI.create(event.getProviderEndpoint()))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(event.getPayload()))
            .build();
    }

